160	    /**
161	     * Returns the stored E.164 {@code telephone} formatted for humans: the recognized country code
162	     * (with its leading {@code '+'}), a space, then the national digits grouped in threes from the
163	     * left and separated by spaces (for example {@code '+61412345678'} renders as
164	     * {@code '+61 412 345 678'}). The split into country code and national number reuses
165	     * {@link #countryCodeOf(String)}, the single definition of that split. Returns {@code null} when
166	     * the owner has no telephone, and returns the raw E.164 value unchanged when it carries no
167	     * recognized country code. This is the single definition of an owner's human-readable telephone.
168	     *
169	     * @return the human-formatted telephone, or {@code null} when the owner has no telephone
170	     */
171	    @Transient
172	    public String getTelephoneDisplay() {
173	        if (this.telephone == null) {
174	            return null;
175	        }
176	        String countryCode = countryCodeOf(this.telephone);
177	        if (countryCode == null) {
178	            return this.telephone;
179	        }
180	        String national = this.telephone.substring(1 + countryCode.length());
181	        StringBuilder display = new StringBuilder("+").append(countryCode);
182	        for (int i = 0; i < national.length(); i += 3) {
183	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
184	        }
185	        return display.toString();
186	    }
