288	    /**
289	     * Builds the derived identity key that consolidates all owner duplicate detection into a
290	     * single value: the normalized E.164 {@code telephone}, the lower-cased {@code email}
291	     * (empty when none) and the {@code householdId} (empty when the owner shares no household),
292	     * joined by {@code '|'}. Two owners are duplicates exactly when their whole identity keys are
293	     * equal, so a difference in any of the three parts (for example two household mates with
294	     * different telephones) yields distinct keys. A {@code null} part contributes the empty string.
295	     *
296	     * @param telephone the normalized E.164 telephone
297	     * @param email the lower-cased email, or {@code null} when none
298	     * @param householdId the shared household identifier, or {@code null} when none
299	     * @return the derived identity key
300	     */
301	    public static String identityKey(String telephone, String email, String householdId) {
302	        return (telephone == null ? "" : telephone) + "|"
303	            + (email == null ? "" : email) + "|"
304	            + (householdId == null ? "" : householdId);
305	    }
306	
307	    /**
308	     * Returns this owner's derived identity key, see
309	     * {@link #identityKey(String, String, String)}.
310	     *
311	     * @return the derived identity key for this owner
312	     */
313	    @Transient
314	    public String getIdentityKey() {
315	        return identityKey(this.telephone, this.email, this.householdId);
316	    }
317	
318	    /**
319	     * Fixed telephone country-code table: the exact national-number length (the count of digits
320	     * following the country code) each country code this application recognizes admits
321	     * ({@code '61'} Australia => 9, {@code '1'} NANP => 10). Keyed by the country-code digits
322	     * without the leading {@code '+'}. A country code absent from this table is not recognized.
323	     */
324	    private static final Map<String, Integer> COUNTRY_CODE_NATIONAL_LENGTHS = Map.of("61", 9, "1", 10);
325	
326	    /**
327	     * Resolves the recognized country code a normalized E.164 telephone carries: the longest entry
328	     * of the fixed country-code table (see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}) whose digits the
329	     * number begins with, so a shorter code can never shadow a longer one. Returns the country-code
330	     * digits without the leading {@code '+'} (for example {@code '61'} for {@code '+61412345678'}),
331	     * or {@code null} when the value is {@code null}, carries no leading {@code '+'}, or begins with
332	     * no recognized country code. This is the single definition of how an E.164 telephone splits
333	     * from its country code, shared by every rule that reasons about a telephone's country code.
334	     *
335	     * @param telephone the normalized E.164 telephone (a {@code '+'} followed by digits), or {@code null}
336	     * @return the recognized country-code digits, or {@code null} when none is recognized
337	     */
338	    public static String countryCodeOf(String telephone) {
339	        if (telephone == null || !telephone.startsWith("+")) {
340	            return null;
341	        }
342	        String digits = telephone.substring(1);
343	        return COUNTRY_CODE_NATIONAL_LENGTHS.keySet().stream()
344	            .filter(digits::startsWith)
345	            .max(Comparator.comparingInt(String::length))
346	            .orElse(null);
347	    }
348	
349	    /**
350	     * Resolves the exact national-number length (the count of digits following the country code) a
351	     * recognized country code admits using the fixed country-code table ({@code '61'} => 9,
352	     * {@code '1'} => 10, see {@link #COUNTRY_CODE_NATIONAL_LENGTHS}). Returns the length, or
353	     * {@code null} when the country code is {@code null} or not recognized (it then carries no
354	     * per-country length rule). This is the single definition of the per-country national-number
355	     * lengths, shared by every rule that relates a telephone's national number to its country code.
356	     *
357	     * @param countryCode the country-code digits without the leading {@code '+'}, or {@code null}
358	     * @return the required national-number length, or {@code null} when the code is not recognized
359	     */
360	    public static Integer nationalNumberLength(String countryCode) {
361	        return countryCode == null ? null : COUNTRY_CODE_NATIONAL_LENGTHS.get(countryCode);
362	    }
363	
364	    /**
365	     * Fixed city-to-region table: the canonical region each known city belongs to
366	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). A city
367	     * absent from this table has no known region.
368	     */
369	    private static final Map<String, String> CITY_REGIONS = Map.of(
370	        "Sydney", "NSW", "Melbourne", "VIC", "Brisbane", "QLD");
371	
372	    /**
373	     * Resolves the canonical region a city belongs to using the fixed city-to-region table
374	     * ({@code Sydney -> NSW}, {@code Melbourne -> VIC}, {@code Brisbane -> QLD}). Returns the
375	     * region string, or {@code null} when the city has no known region. This is the single
376	     * definition of the city-to-region mapping, shared by every rule that derives a region
377	     * from an owner's city.
378	     *
379	     * @param city the city to resolve
380	     * @return the canonical region, or {@code null} when the city has no known region
381	     */
382	    public static String regionForCity(String city) {
383	        return CITY_REGIONS.get(city);
384	    }
385	
386	    /**
387	     * Fixed region-to-postcode table: the inclusive {@code {low, high}} 4-digit postcode range
388	     * each region admits ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
389	     * A region absent from this table has no fixed range.
390	     */
391	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
392	        "NSW", new int[] {2000, 2099}, "VIC", new int[] {3000, 3099}, "QLD", new int[] {4000, 4099});
393	
394	    /**
395	     * Resolves the inclusive {@code {low, high}} 4-digit postcode range a region admits using the
396	     * fixed region-to-postcode table ({@code NSW 2000-2099}, {@code VIC 3000-3099},
397	     * {@code QLD 4000-4099}). Returns the range, or {@code null} when the region is {@code null} or
398	     * has no fixed range (any 4-digit postcode is then admitted). This is the single definition of
399	     * the region-to-postcode ranges, shared by every rule that relates a postcode to a region.
400	     *
401	     * @param region the region to resolve, or {@code null}
402	     * @return the inclusive {@code {low, high}} range, or {@code null} when the region has none
403	     */
404	    public static int[] postcodeRangeForRegion(String region) {
405	        return region == null ? null : REGION_POSTCODE_RANGES.get(region);
406	    }
407	
408	    /**
409	     * Resolves the canonical region a postcode belongs to by finding the fixed region-to-postcode
410	     * range that contains it ({@code NSW 2000-2099}, {@code VIC 3000-3099}, {@code QLD 4000-4099}).
411	     * Returns the region string, or {@code null} when the postcode is {@code null}, not a 4-digit
412	     * value, or falls in no known range. This is the single definition of the postcode-to-region
413	     * mapping, shared by every rule that derives a region from a postcode.
414	     *
415	     * @param postcode the postcode to resolve
416	     * @return the canonical region, or {@code null} when the postcode maps to no known region
417	     */
418	    public static String regionForPostcode(String postcode) {
419	        if (postcode == null || !postcode.matches("^[0-9]{4}$")) {
420	            return null;
421	        }
422	        int value = Integer.parseInt(postcode);
423	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
424	            int[] range = entry.getValue();
425	            if (value >= range[0] && value <= range[1]) {
426	                return entry.getKey();
427	            }
428	        }
429	        return null;
430	    }
431	
432	    /**
433	     * Returns the canonical region this owner belongs to. The owner's {@code postcode} is preferred:
434	     * when it falls in a known region range (see {@link #regionForPostcode(String)}) that region is
435	     * used, disambiguating cities that share a name. Only when the postcode is absent or in no known
436	     * range does derivation fall back to the fixed city-to-region table (see
437	     * {@link #regionForCity(String)}). Returns {@code null} when neither the postcode nor the city
438	     * resolves to a known region. This is the single definition of an owner's region, shared by
439	     * every rule that derives a region from an owner.
440	     *
441	     * @return the owner's canonical region, or {@code null} when it has no known region
442	     */
443	    @Transient
444	    public String getRegion() {
445	        String region = regionForPostcode(this.postcode);
446	        return region != null ? region : regionForCity(this.city);
447	    }
448	
449	    /**
450	     * Resolves whether an {@code email} counts as present for membership purposes: the value is
451	     * non-null and not blank. Returns {@code false} otherwise. This is the single definition of an
452	     * owner "having an email", shared by every rule that turns email presence into a derived value
453	     * (its membership factor and its {@code contactPreference}).
454	     *
455	     * @param email the owner's email, or {@code null}
456	     * @return {@code true} when the email is present and not blank
457	     */
458	    public static boolean hasEmail(String email) {
459	        return email != null && !email.isBlank();
460	    }
461	
462	    /**
463	     * Resolves whether an owner with the given {@code namesakeCount} has no namesakes: the count is
464	     * present and equal to {@code 0}. Returns {@code false} when the count is {@code null} (unknown)
465	     * or positive. This is the single definition of the "no namesakes" membership factor, shared by
466	     * every rule that rewards an owner for being unique by name.
467	     *
468	     * @param namesakeCount the owner's namesake count, or {@code null}
469	     * @return {@code true} when the owner is known to have no namesakes
470	     */
471	    public static boolean hasNoNamesakes(Integer namesakeCount) {
472	        return namesakeCount != null && namesakeCount == 0;
473	    }
474	
475	    /**
476	     * Resolves whether an owner registered on {@code registrationDate} has long tenure as of
477	     * {@code asOf}: the whole number of days between the two dates exceeds {@code 365}. Returns
478	     * {@code false} when {@code registrationDate} is absent, so the owner has no derivable tenure;
479	     * because a newly created owner has zero tenure, it never counts as long-tenured. This is the
480	     * single definition of the "long tenure" membership factor, shared by every rule that rewards
481	     * an owner for tenure beyond a year.
482	     *
483	     * @param registrationDate the owner's registration date, or {@code null}
484	     * @param asOf the date the tenure is measured against
485	     * @return {@code true} when the owner's tenure exceeds 365 days
486	     */
487	    public static boolean hasLongTenure(LocalDate registrationDate, LocalDate asOf) {
488	        return registrationDate != null && ChronoUnit.DAYS.between(registrationDate, asOf) > 365;
489	    }
490	
491	    /**
492	     * Resolves whether an owner with the given {@code householdMemberCount} belongs to a large
493	     * household: the count is present and at least {@code 3}. Returns {@code false} when the count is
494	     * {@code null} (unknown) or smaller. This is the single definition of the "large household"
495	     * membership factor, shared by every rule that rewards an owner for a household of three or more.
496	     *
497	     * @param householdMemberCount the number of owners sharing the household, or {@code null}
498	     * @return {@code true} when the owner is known to belong to a household of three or more
499	     */
500	    public static boolean hasLargeHousehold(Integer householdMemberCount) {
501	        return householdMemberCount != null && householdMemberCount >= 3;
502	    }
503	
504	    /**
505	     * Returns this owner's membership points. Points start at {@code 0} and accumulate the membership
506	     * factors: {@code 2} when an email is present, {@code 1} when the owner has no namesakes
507	     * (namesakeCount is 0), {@code 2} when the owner belongs to a household of three or more, and
508	     * {@code 3} when the owner's tenure exceeds 365 days. Because a newly created owner has zero
509	     * tenure, the tenure points are never awarded on creation. This is the single source the
510	     * membership level is derived from (see {@link #getMembershipLevel()}).
511	     *
512	     * @return the owner's membership points
513	     */
514	    @Transient
515	    public Integer getMembershipPoints() {
516	        LocalDate today = LocalDate.now();
517	        int points = 0;
518	        if (hasEmail(this.email)) {
519	            points += 2;
520	        }
521	        if (hasNoNamesakes(this.namesakeCount)) {
522	            points += 1;
523	        }
524	        if (hasLargeHousehold(this.householdMemberCount)) {
525	            points += 2;
526	        }
527	        if (hasLongTenure(this.registrationDate, today)) {
528	            points += 3;
529	        }
530	        return points;
531	    }
532	
533	    /**
534	     * Returns this owner's numeric membership level, derived from its membership points (see
535	     * {@link #getMembershipPoints()}): {@code 1} for {@code 0-1} points, {@code 2} for {@code 2-3},
536	     * {@code 3} for {@code 4-5}, and {@code 4} for {@code 6} or more points.
537	     *
538	     * @return the owner's membership level
539	     */
540	    @Transient
541	    public Integer getMembershipLevel() {
542	        int points = getMembershipPoints();
543	        if (points >= 6) {
544	            return 4;
545	        }
546	        if (points >= 4) {
547	            return 3;
548	        }
549	        if (points >= 2) {
550	            return 2;
551	        }
552	        return 1;
553	    }
554	
555	    /**
556	     * Returns this owner's membership number formatted as {@code '<customerCode>-M<YY>'}, where YY is
557	     * the last two digits of the registrationDate year, e.g. {@code 'NSW-A1B2C3D4-M26'}. Returns
558	     * {@code null} when the owner has no customer code or registration date.
559	     *
560	     * @return the owner's membership number, or {@code null} when it cannot be derived
561	     */
562	    @Transient
563	    public String getMembershipNumber() {
564	        if (this.customerCode == null || this.registrationDate == null) {
565	            return null;
566	        }
567	        return String.format("%s-M%02d", this.customerCode, this.registrationDate.getYear() % 100);
568	    }
569	
570	    /**
571	     * Returns this owner's check digit: a single Luhn check digit (0-9) over the digits contained in
572	     * the owner's customerCode. Returns {@code null} when the owner has no customer code.
573	     *
574	     * @return the owner's check digit, or {@code null} when it has no customer code
575	     */
576	    @Transient
577	    public Integer getCheckDigit() {
578	        if (this.customerCode == null) {
579	            return null;
580	        }
581	        String code = this.customerCode;
582	        int sum = 0;
583	        boolean dbl = true;
584	        for (int i = code.length() - 1; i >= 0; i--) {
585	            char c = code.charAt(i);
586	            if (c < '0' || c > '9') {
587	                continue;
588	            }
589	            int d = c - '0';
590	            if (dbl) {
591	                d *= 2;
592	                if (d > 9) {
593	                    d -= 9;
594	                }
595	            }
596	            sum += d;
597	            dbl = !dbl;
598	        }
599	        return (10 - (sum % 10)) % 10;
600	    }
601	
602	    /**
603	     * Returns this owner's age band, derived from {@code birthDate} computed against
604	     * {@code registrationDate}: the whole number of years between the two dates places the owner in
605	     * {@code 'MINOR'} (under 18), {@code 'ADULT'} (18 to 64 inclusive) or {@code 'SENIOR'} (65 or
606	     * older). Returns {@code null} when the owner has no birth date or no registration date, so the
607	     * band cannot be derived. This is the single definition of an owner's age band.
608	     *
609	     * @return the owner's age band, or {@code null} when it cannot be derived
610	     */
611	    @Transient
612	    public String getAgeBand() {
613	        if (this.birthDate == null || this.registrationDate == null) {
614	            return null;
615	        }
616	        int age = java.time.Period.between(this.birthDate, this.registrationDate).getYears();
617	        if (age < 18) {
618	            return "MINOR";
619	        }
620	        if (age < 65) {
621	            return "ADULT";
622	        }
623	        return "SENIOR";
624	    }
625	
626	    protected Set<Pet> getPetsInternal() {
627	        if (this.pets == null) {
628	            this.pets = new HashSet<>();
629	        }
630	        return this.pets;
631	    }
632	
633	    protected void setPetsInternal(Set<Pet> pets) {
634	        this.pets = pets;
635	    }
636	
637	    public List<Pet> getPets() {
638	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
639	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
640	        return Collections.unmodifiableList(sortedPets);
641	    }
642	
643	    public void setPets(List<Pet> pets) {
644	        this.pets = new HashSet<>(pets);
645	    }
646	
647	    public void addPet(Pet pet) {
648	        getPetsInternal().add(pet);
649	        pet.setOwner(this);
650	    }
651	
652	    /**
653	     * Return the Pet with the given name, or null if none found for this Owner.
654	     *
655	     * @param name to test
656	     * @return true if pet name is already in use
657	     */
658	    public Pet getPet(String name) {
659	        return getPet(name, false);
660	    }
661	
662	    /**
663	     * Return the Pet with the given name, or null if none found for this Owner.
664	     *
665	     * @param name to test
666	     * @return true if pet name is already in use
667	     */
668	    public Pet getPet(String name, boolean ignoreNew) {
669	        name = name.toLowerCase();
670	        for (Pet pet : getPetsInternal()) {
671	            if (!ignoreNew || !pet.isNew()) {
672	                String compName = pet.getName();
673	                compName = compName.toLowerCase();
674	                if (compName.equals(name)) {
675	                    return pet;
676	                }
677	            }
678	        }
679	        return null;
680	    }
681	
682	    public Pet getPet(Integer petId) {
683	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
684	    }
685	
686	    @Override
687	    public String toString() {
688	        return new ToStringCreator(this)
689	
690	            .append("id", this.getId())
691	            .append("new", this.isNew())
692	            .append("lastName", this.getLastName())
693	            .append("firstName", this.getFirstName())
694	            .append("address", this.address)
695	            .append("city", this.city)
696	            .append("telephone", this.telephone)
697	            .append("email", this.email)
698	            .toString();
699	    }
700	}
